'use strict';

// Load modules

const Boom = require('boom');
const Hoek = require('hoek');
const Iron = require('iron');
const Items = require('items');


// Declare internals

const internals = {
    version: '2'
};


exports = module.exports = internals.Socket = function (ws, listener) {

    this._ws = ws;
    this._listener = listener;
    this._helloed = false;
    this._pinged = false;
    this._subscriptions = {};

    this.id = this._listener._generateId();
    this.app = {};
    this.auth = {
        isAuthenticated: false,
        credentials: null,
        artifacts: null
    };

    ws.on('message', (message) => this._onMessage(message));
    this._authenticate();
};


internals.Socket.prototype.disconnect = function () {

    this._ws.close();
};


internals.Socket.prototype.send = function (message) {

    const response = {
        type: 'update',
        message: message
    };

    return this._send(response);
};


internals.Socket.prototype._send = function (message) {

    if (this._ws.readyState !== 1) {        // Open
        return;
    }

    internals.stringify(message, (err, string) => {

        if (err) {
            this._listener._connection.server.log(['nes', 'serialization', 'error'], message.type);

            if (message.id) {
                return this._error(Boom.internal('Failed serializing message'), message);
            }

            return;
        }

        this._ws.send(string);
    });
};


internals.Socket.prototype._error = function (err, request) {

    err = Boom.wrap(err);

    const message = Hoek.clone(err.output);
    delete message.payload.statusCode;
    message.headers = this._filterHeaders(message.headers);

    if (request) {
        message.type = request.type;
        message.id = request.id;
        message.path = request.path;
    }

    return this._send(message);
};


internals.Socket.prototype._onMessage = function (message) {

    internals.parse(message, (err, request) => {

        if (err ||
            !request.type) {

            return this._error(Boom.badRequest('Cannot parse message'), request);
        }

        if (!request.id) {
            return this._error(Boom.badRequest('Message missing id'), request);
        }

        // Initialization and Authentication

        if (request.type === 'ping') {
            this._pinged = true;
            return;
        }

        if (request.type === 'hello') {
            return this._processHello(request);
        }

        if (!this._helloed) {
            return this._error(Boom.badRequest('Connection is not initialized'), request);
        }

        // Endpoint request

        if (request.type === 'request') {
            return this._processRequest(request);
        }

        // Custom message request

        if (request.type === 'message') {
            return this._processMessage(request);
        }

        // Subscriptions

        if (request.type === 'sub') {
            return this._processSubscription(request);
        }

        if (request.type === 'unsub') {
            return this._processUnsubscribe(request);           // Does not return a response
        }

        // Unknown

        return this._error(Boom.badRequest('Unknown message type'), request);
    });
};


internals.Socket.prototype._processHello = function (request) {

    if (this._helloed) {
        return this._error(Boom.badRequest('Connection already initialized'), request);
    }

    if (request.version !== internals.version) {
        return this._error(Boom.badRequest('Incorrect protocol version (expected ' + internals.version + ' but received ' + (request.version || 'none') + ')'), request);
    }

    if (!request.auth &&
        !this.auth.isAuthenticated &&
        this._listener._authRequired()) {

        return this._error(Boom.unauthorized('Connection requires authentication'), request);
    }

    if (request.auth &&
        this.auth.isAuthenticated) {        // Authenticated using a cookie during upgrade

        return this._error(Boom.badRequest('Connection already authenticated'), request);
    }

    this._helloed = true;                   // Prevents the client from reusing the socket if erred (leaves socket open to ensure client gets the error response)

    const response = {
        type: 'hello',
        id: request.id,
        heartbeat: this._listener._settings.heartbeat,
        socket: this.id
    };

    if (!request.auth) {
        return this._processHelloSubscriptions(request, response);
    }

    const config = this._listener._settings.auth;
    if (config.type === 'direct') {
        const route = this._listener._connection.lookup(config.id);
        this._listener._connection.inject({ url: route.path, method: 'auth', headers: request.auth.headers, allowInternals: true }, (res) => {

            if (res.statusCode !== 200) {
                return this._error(Boom.unauthorized(res.result.message), request);
            }

            this.auth = {
                isAuthenticated: true,
                credentials: res.result.credentials,
                artifacts: res.result.artifacts
            };

            return this._processHelloSubscriptions(request, response);
        });

        return;
    }

    Iron.unseal(request.auth, config.password, config.iron || Iron.defaults, (err, credentials) => {

        if (err) {
            return this._error(Boom.unauthorized('Invalid token'), request);
        }

        this.auth = {
            isAuthenticated: true,
            credentials: credentials,
            artifacts: null
        };

        return this._processHelloSubscriptions(request, response);
    });
};


internals.Socket.prototype._processHelloSubscriptions = function (request, response) {

    const each = (path, nextPath) => {

        this._listener._subscribe(path, this, (err) => {

            if (err) {
                err.path = path;
            }

            return nextPath(err);
        });
    };

    Items.serial(request.subs || [], each, (err) => {

        if (err) {
            return this._error(err, { type: 'hello', id: request.id, path: err.path });
        }

        if (this._listener._settings.onConnection) {
            this._listener._settings.onConnection(this);
        }

        return this._send(response);
    });
};


internals.Socket.prototype._processRequest = function (request) {

    let method = request.method;
    if (!method) {
        return this._error(Boom.badRequest('Message missing method'), request);
    }

    let path = request.path;
    if (!path) {
        return this._error(Boom.badRequest('Message missing path'), request);
    }

    if (request.headers &&
        internals.caseInsensitiveKey(request.headers, 'authorization')) {

        return this._error(Boom.badRequest('Cannot include an Authorization header'), request);
    }

    if (path[0] !== '/') {              // Route id
        const route = this._listener._connection.lookup(path);
        if (!route) {
            return this._error(Boom.notFound(), request);
        }

        path = route.path;
        method = route.method;

        if (method === '*') {
            return this._error(Boom.badRequest('Cannot use route id with wildcard method route config'), request);
        }
    }

    if (this._listener._settings.auth &&
        path === this._listener._settings.auth.endpoint) {

        return this._error(Boom.notFound(), request);
    }

    const shot = {
        method: method,
        url: path,
        payload: request.payload,
        headers: request.headers,
        credentials: this.auth.credentials,
        artifacts: this.auth.artifacts,
        plugins: {
            nes: {
                socket: this
            }
        }
    };

    this._listener._connection.inject(shot, (res) => {

        const response = {
            type: 'request',
            id: request.id,
            statusCode: res.statusCode,
            payload: res.result,
            headers: this._filterHeaders(res.headers)
        };

        return this._send(response);
    });
};


internals.Socket.prototype._processMessage = function (request) {

    if (!this._listener._settings.onMessage) {
        return this._error(Boom.notImplemented(), request);
    }

    this._listener._settings.onMessage(this, request.message, (message) => {

        if (message instanceof Error) {
            return this._error(message, request);
        }

        const response = {
            type: 'message',
            id: request.id,
            message: message
        };

        return this._send(response);
    });
};


internals.Socket.prototype._processSubscription = function (request) {

    this._listener._subscribe(request.path, this, (err) => {

        if (err) {
            return this._error(err, request);
        }

        const response = {
            type: 'sub',
            id: request.id,
            path: request.path
        };

        return this._send(response);
    });
};


internals.Socket.prototype._processUnsubscribe = function (request) {

    const sub = this._subscriptions[request.path];
    if (sub) {
        sub.remove(this, request.path);
        delete this._subscriptions[request.path];
    }
};


internals.Socket.prototype._authenticate = function () {

    const config = this._listener._settings.auth;
    if (!config) {
        return;
    }

    const cookies = this._ws.upgradeReq.headers.cookie;
    if (!cookies) {
        return;
    }

    this._listener._connection.states.parse(cookies, (ignoreErr, state, failed) => {

        const auth = state[config.cookie];
        if (auth) {
            this.auth = {
                isAuthenticated: true,
                credentials: auth.credentials,
                artifacts: auth.artifacts
            };
        }
    });
};


internals.Socket.prototype._filterHeaders = function (headers) {

    const filter = this._listener._settings.headers;
    if (!filter) {
        return undefined;
    }

    if (filter === '*') {
        return headers;
    }

    const filtered = {};
    const fields = Object.keys(headers);
    for (let i = 0; i < fields.length; ++i) {
        const field = fields[i];
        if (filter.indexOf(field.toLowerCase()) !== -1) {
            filtered[field] = headers[field];
        }
    }

    return filtered;
};


internals.parse = function (message, next) {

    let obj = null;
    let error = null;

    try {
        obj = JSON.parse(message);
    }
    catch (err) {
        error = err;
    }

    return next(error, obj);
};


internals.stringify = function (message, next) {

    let string = null;
    let error = null;

    try {
        string = JSON.stringify(message);
    }
    catch (err) {
        error = err;
    }

    return next(error, string);
};


internals.caseInsensitiveKey = function (object, key) {

    const keys = Object.keys(object);
    for (let i = 0; i < keys.length; ++i) {
        const current = keys[i];
        if (key === current.toLowerCase()) {
            return object[current];
        }
    }

    return undefined;
};

'use strict';

// Load modules

const Boom = require('boom');
const Call = require('call');
const Hoek = require('hoek');
const Joi = require('joi');
const Ws = require('ws');
const Socket = require('./socket');


// Declare internals

const internals = {
    counter: {
        min: 10000,
        max: 99999
    }
};


exports = module.exports = internals.Listener = function (connection, settings) {

    this._connection = connection;
    this._settings = settings;
    this._sockets = new internals.Sockets();
    this._router = new Call.Router();
    this._authRoute = this._settings.auth && connection.lookup(this._settings.auth.id);
    this._socketCounter = internals.counter.min;
    this._heartbeat = null;
    this._timeout = null;

    // WebSocket listener

    this._wss = new Ws.Server({ server: connection.listener });

    this._wss.on('connection', (ws) => {

        this._add(ws);
    });

    this._wss.on('error', Hoek.ignore);

    // Register with connection

    connection.plugins.nes = {
        _listener: this
    };

    // Start heartbeats

    this._beat();
};


internals.Listener.prototype._add = function (ws) {

    // Socket object

    const socket = new Socket(ws, this);

    // Subscriptions

    this._sockets.add(socket);

    ws.once('close', (code, message) => {

        this._sockets.remove(socket);
        const subs = Object.keys(socket._subscriptions);
        for (let i = 0; i < subs.length; ++i) {
            const subscribers = socket._subscriptions[subs[i]];
            subscribers.remove(socket);
        }

        socket._subscriptions = {};

        if (this._settings.onDisconnection) {
            this._settings.onDisconnection(socket);
        }
    });
};


internals.Listener.prototype._close = function () {

    clearTimeout(this._heartbeat);
    clearTimeout(this._timeout);

    this._wss.close();
};


internals.Listener.prototype._authRequired = function () {

    if (!this._authRoute) {
        return false;
    }

    const auth = this._connection.auth.lookup(this._authRoute);
    if (!auth) {
        return false;
    }

    return auth.mode === 'required';
};


internals.Listener.prototype._beat = function () {

    if (!this._settings.heartbeat) {
        return;
    }

    if (this._heartbeat &&                              // Skip the first time
        this._sockets.length()) {

        // Send heartbeats

        const update = {
            type: 'ping'
        };

        this._sockets.forEach((socket) => {

            socket._send(update);
        });

        // Verify client responded

        this._timeout = setTimeout(() => {

            this._sockets.forEach((socket) => {

                if (!socket._pinged) {
                    socket.disconnect();
                }

                socket._pinged = false;
            });
        }, this._settings.heartbeat.timeout);
    }

    // Schedule next heartbeat

    this._heartbeat = setTimeout(() => {

        this._beat();
    }, this._settings.heartbeat.interval);
};


internals.Listener.broadcast = function (message) {

    const update = {
        type: 'update',
        message: message
    };

    const connections = this.connections;
    for (let i = 0; i < connections.length; ++i) {
        const connection = connections[i];
        if (connection.plugins.nes) {
            connection.plugins.nes._listener._broadcast(update);
        }
    }
};


internals.Listener.prototype._broadcast = function (update) {

    this._sockets.forEach((socket) => {

        socket._send(update);
    });
};


internals.subSchema = Joi.object({
    filter: Joi.func(),                                             // function (path, update, options, next), where options: { credentials, params }
    onSubscribe: Joi.func(),                                        // function (socket)
    onUnsubscribe: Joi.func(),                                      // function (socket)
    auth: Joi.object({
        mode: Joi.string().valid('required', 'optional'),
        scope: Joi.array().items(Joi.string()).single().min(1),
        entity: Joi.valid('user', 'app', 'any')
    })
        .allow(false)
});


internals.Listener.subscription = function (path, options) {

    Hoek.assert(path, 'Subscription missing path');
    Joi.assert(options, internals.subSchema, 'Invalid subscription options: ' + path);

    const settings = Hoek.clone(options || {});

    // Auth configuration

    const auth = settings.auth;
    if (auth) {
        if (auth.scope) {
            if (typeof auth.scope === 'string') {
                auth.scope = [auth.scope];
            }

            for (let i = 0; i < auth.scope.length; ++i) {
                if (/{([^}]+)}/.test(auth.scope[i])) {
                    auth.hasScopeParameters = true;
                    break;
                }
            }
        }

        auth.mode = auth.mode || 'required';
    }

    // Path configuration

    const route = {
        method: 'sub',
        path: path
    };

    const config = {
        subscribers: new internals.Subscribers(settings),
        filter: settings.filter,
        auth: auth
    };

    const connections = this.connections;
    for (let i = 0; i < connections.length; ++i) {
        const connection = connections[i];
        if (connection.plugins.nes) {
            connection.plugins.nes._listener._router.add(route, config);
        }
    }
};


internals.Listener.publish = function (path, update, options) {

    Hoek.assert(path && path[0] === '/', 'Missing or invalid subscription path:', path || 'empty');

    options = options || {};

    const message = {
        type: 'pub',
        path: path,
        message: update
    };

    const connections = this.connections;
    for (let i = 0; i < connections.length; ++i) {
        const connection = connections[i];
        if (connection.plugins.nes) {
            connection.plugins.nes._listener._publish(path, message, options);
        }
    }
};


internals.Listener.prototype._publish = function (path, update, options) {

    const sub = this._router.route('sub', path);
    if (sub.isBoom) {
        return;
    }

    const route = sub.route;
    route.subscribers.forEach(sub.paramsArray.length ? path : null, (socket) => {       // Filter on path if has parameters

        if (!route.filter) {
            socket._send(update);
        }
        else {
            route.filter(path, update.message, { credentials: socket.auth.credentials, params: sub.params, internal: options.internal }, (isMatch) => {

                if (isMatch) {
                    return socket._send(update);
                }
            });
        }
    });
};


internals.Listener.prototype._subscribe = function (path, socket, next) {

    // Errors include subscription context in messages in case returned as connection errors

    if (path.indexOf('?') !== -1) {
        return next(Boom.badRequest('Subscription path cannot contain query'));
    }

    if (socket._subscriptions[path]) {
        return next();
    }

    const match = this._router.route('sub', path);
    if (match.isBoom) {
        return next(Boom.notFound('Subscription not found'));
    }

    const auth = this._connection.auth.lookup({ settings: { auth: match.route.auth } });         // Create a synthetic route
    if (auth) {
        const credentials = socket.auth.credentials;
        if (credentials) {

            // Check scope

            if (auth.scope) {
                let scopes = auth.scope;
                if (auth.hasScopeParameters) {
                    scopes = [];
                    const context = { params: match.params };
                    for (let i = 0; i < auth.scope.length; ++i) {
                        scopes[i] = Hoek.reachTemplate(context, auth.scope[i]);
                    }
                }

                if (!credentials.scope ||
                    (typeof credentials.scope === 'string' ? scopes.indexOf(credentials.scope) === -1 : !Hoek.intersect(scopes, credentials.scope).length)) {

                    return next(Boom.forbidden('Insufficient scope to subscribe, expected any of: ' + scopes));
                }
            }

            // Check entity

            const entity = auth.entity || 'any';
            if (entity === 'user' &&
                !credentials.user) {

                return next(Boom.forbidden('Application credentials cannot be used on a user subscription'));
            }

            if (entity === 'app' &&
                credentials.user) {

                return next(Boom.forbidden('User credentials cannot be used on an application subscription'));
            }
        }
        else if (auth.mode === 'required') {
            return next(Boom.unauthorized('Authentication required to subscribe'));
        }
    }

    match.route.subscribers.add(socket, path);
    socket._subscriptions[path] = match.route.subscribers;
    return next();
};


internals.Listener.eachSocket = function (each, options) {

    options = options || {};

    const connections = this.connections;
    for (let i = 0; i < connections.length; ++i) {
        const connection = connections[i];
        if (connection.plugins.nes) {
            connection.plugins.nes._listener._eachSocket(each, options);
        }
    }
};


internals.Listener.prototype._eachSocket = function (each, options) {

    const subscription = options.subscription;
    if (!subscription) {
        return this._sockets.forEach(each);
    }

    const sub = this._router.route('sub', subscription);
    if (sub.isBoom) {
        return;
    }

    const route = sub.route;
    route.subscribers.forEach(sub.paramsArray.length ? subscription : null, (socket) => each(socket));   // Filter on path if has parameters
};


internals.Listener.prototype._generateId = function () {

    const id = Date.now() + ':' + this._connection.info.id + ':' + this._socketCounter++;
    if (this._socketCounter > internals.counter.max) {
        this._socketCounter = internals.counter.min;
    }

    return id;
};


// Sockets manager

internals.Sockets = function () {

    this._items = {};
};


internals.Sockets.prototype.add = function (socket) {

    this._items[socket.id] = socket;
};


internals.Sockets.prototype.remove = function (socket) {

    delete this._items[socket.id];
};


internals.Sockets.prototype.forEach = function (each) {

    const items = Object.keys(this._items);
    for (let i = 0; i < items.length; ++i) {
        each(this._items[items[i]]);
    }
};


internals.Sockets.prototype.length = function () {

    return Object.keys(this._items).length;
};


// Subscribers manager

internals.Subscribers = function (options) {

    this._onSubscribe = options.onSubscribe;
    this._onUnsubscribe = options.onUnsubscribe;
    this._items = {};
};


internals.Subscribers.prototype.add = function (socket, path) {

    const item = this._items[socket.id];
    if (item) {
        item.paths.push(path);
    }
    else {
        this._items[socket.id] = { socket: socket, paths: [path] };
    }

    if (this._onSubscribe) {
        this._onSubscribe(socket, path);
    }
};


internals.Subscribers.prototype.remove = function (socket, path) {

    const item = this._items[socket.id];
    if (!item) {
        return;
    }

    if (!path) {
        if (this._onUnsubscribe) {
            for (let i = 0; i < item.paths.length; ++i) {
                this._onUnsubscribe(socket, item.paths[i]);
            }
        }

        delete this._items[socket.id];
        return;
    }

    const pos = item.paths.indexOf(path);
    if (item.paths.length === 1) {
        delete this._items[socket.id];
    }
    else {
        item.paths.splice(pos, 1);
    }

    if (this._onUnsubscribe) {
        this._onUnsubscribe(socket, path);
    }
};


internals.Subscribers.prototype.forEach = function (path, each) {

    const items = Object.keys(this._items);
    for (let i = 0; i < items.length; ++i) {
        const item = this._items[items[i]];
        if (!path ||
            item.paths.indexOf(path) !== -1) {

            each(item.socket);
        }
    }
};

